// Porous Deep - relief (displacement). STATIC (no t/u_time). Runs INSIDE map().
// Deep-hole variant of "Porous Bone". The holes are DRILLED, not embossed.
//
// WHY A DIFFERENT METHOD: the shallow version subtracts a bump term
// (d_surf += DEPTH*carve). That term makes d_surf a non-Lipschitz field whose
// gradient is ~DEPTH/RIM, so pushing DEPTH up to get deeper holes makes the
// marcher overshoot the shell and produces white speckles inside the holes.
// Here the holes are removed with a CSG DIFFERENCE instead: max(d_surf, -d_hole).
// The max of two valid SDFs is still a valid SDF, so the depth is limited only
// by the geometry -- no speckles, no slowdown factor needed.
//
// In scope: d_surf, p, pModel.
// TIP: enable the SHELL render mode to get see-through holes with visible inner
// walls (the shell is applied AFTER this block, so it hollows the drilled solid).

float DENSITY   = 6.0;    // hole density (cells per unit)     [3 .. 12]
float R_MIN     = 0.12;   // smallest hole radius              [0.06 .. 0.22]
float R_MAX     = 0.52;   // largest  hole radius              [0.35 .. 0.60]
float SIZE_BIAS = 2.2;    // >1 = many small, few big holes    [1.0 .. 4.0]
float FILL      = 0.85;   // fraction of cells that get a hole [0.5 .. 1.0]
float ELONG     = 1.45;   // holes stretched INWARD (depth)    [1.0 .. 2.5]
float ROUND     = 0.030;  // rim rounding radius               [0.0 .. 0.08]

// Radial frame: the holes are drilled along the local "inward" direction, so on
// a closed surface they bore toward the centre instead of all pointing the same
// way. normalize() guards the origin, where any direction is fine.
vec3 inward = normalize(pModel + vec3(1e-5));

vec3 vp = pModel * DENSITY;
vec3 vi = floor(vp);
vec3 vf = fract(vp);

// d_hole = union of the drill volumes (negative inside). Union = min of SDFs.
float d_hole = 8.0;

for (int gx = -1; gx <= 1; gx++)
for (int gy = -1; gy <= 1; gy++)
for (int gz = -1; gz <= 1; gz++) {
    vec3 g = vec3(float(gx), float(gy), float(gz));
    vec3 c = vi + g;

    // 3 independent randoms per cell: position, radius, existence.
    vec3 o = fract(sin(vec3(
        dot(c, vec3(127.1, 311.7,  74.7)),
        dot(c, vec3(269.5, 183.3, 246.1)),
        dot(c, vec3(113.5, 271.9, 124.6)))) * 43758.5453);

    float rr = fract(sin(dot(c, vec3(419.2, 371.9, 668.5))) * 24634.6345);
    float ex = fract(sin(dot(c, vec3(157.3, 113.7, 271.1))) * 15731.7431);

    float rad = mix(R_MIN, R_MAX, safePow(rr, SIZE_BIAS));
    rad *= step(1.0 - FILL, ex);

    // vector from the cell's feature point, in cell units
    vec3 r = g + o - vf;

    // ELLIPSOID stretched along 'inward': the drill is longer than it is wide,
    // which is what makes the cavity DEEP instead of a spherical dimple.
    // Squash the radial component before measuring -> longer axis inward.
    vec3 rw = r - inward * dot(r, inward) * (1.0 - 1.0 / ELONG);

    d_hole = min(d_hole, length(rw) - rad);
}

d_hole /= DENSITY;   // back to model units

// CSG DIFFERENCE with rounding: solid minus holes.
// Plain version would be max(d_surf, -d_hole); the smooth-max variant rounds the
// rim over ROUND so the lips look eroded rather than knife-cut, while staying a
// well-behaved distance field.
float a = d_surf;
float b = -d_hole;
float h = clamp(0.5 - 0.5 * (a - b) / max(ROUND, 1e-4), 0.0, 1.0);
d_surf = mix(a, b, h) + ROUND * h * (1.0 - h);
